import{_ as i,a0 as l,w as d,s as o,I as n,x as a,a1 as t,A as p,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"ZOMBIES：軟件開發和測試中的構建與拓展（二） | LCTT x X-CMD","titleTemplate":false,"description":"ZOMBIES：軟件開發和測試中的構建與拓展（二） | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"ZOMBIES：軟件開發和測試中的構建與拓展（二） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"ZOMBIES：軟件開發和測試中的構建與拓展（二） | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20210202 How I build and expand application development and testing","title":"ZOMBIES：軟件開發和測試中的構建與拓展（二）","tag":"202305","desc":""},"relativePath":"202305/20210202 How I build and expand application development and testing.md","filePath":"[post].md"}'),c={name:"202305/20210202 How I build and expand application development and testing.md"};function h(g,s,u,b,k,m){const e=l("Link");return d(),o("div",null,[s[18]||(s[18]=n("h1",{id:"zombies-軟件開發和測試中的構建與拓展-二",tabindex:"-1"},[a("ZOMBIES：軟件開發和測試中的構建與拓展（二） "),n("a",{class:"header-anchor",href:"#zombies-軟件開發和測試中的構建與拓展-二","aria-label":"Permalink to “ZOMBIES：軟件開發和測試中的構建與拓展（二）”"},"​")],-1)),s[19]||(s[19]=n("blockquote",null,[n("p",null,"在開發初期只對單個元素進行編碼和測試，之後再拓展到多個元素上。")],-1)),s[20]||(s[20]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202305/16/154949rgu89gbzpzp1p0et.jpg",alt:""})],-1)),n("p",null,[s[1]||(s[1]=a("在 ",-1)),t(e,{href:"https://linux.cn/article-15808-1.html"},{default:p(()=>[...s[0]||(s[0]=[a("上一篇文章",-1)])]),_:1}),s[2]||(s[2]=a(" 中我已經解釋了為什麼把所有編程問題當作一羣喪屍一次性處理是錯誤的。我也解釋了 ZOMBIES 方法中的第一條：最簡場景。本文中我將進一步介紹接下來的兩條：單元素場景和多元素場景。",-1))]),s[21]||(s[21]=r(`<p>ZOMBIES 表示以下首字母縮寫：</p><ul><li><strong>Z</strong> – 最簡場景（Zero）</li><li><strong>O</strong> – 單元素場景（One）</li><li><strong>M</strong> – 多元素場景（Many or more complex）</li><li><strong>B</strong> – 邊界行為（Boundary behaviors）</li><li><strong>I</strong> – 接口定義（Interface definition）</li><li><strong>E</strong> – 處理特殊行為（Exercise exceptional behavior）</li><li><strong>S</strong> – 簡單場景用簡單的解決方案（Simple scenarios, simple solutions）</li></ul><p>在上一篇文章中，通過應用了最簡場景，你在代碼裏構建了一條最簡可行通路。這個代碼裏沒有任何業務處理邏輯。現在是時候向系統中添加一個元素了。</p><p>最簡場景表示系統中什麼也沒有，這是一個空的用例，我們什麼也不用關心。單元素場景代表我們有一個元素需要關心考慮。這個單一元素可能是集合中的一個元素、一個訪問着或者一個需要處理的事件。</p><p>對於多元素場景，我們需要處理更復雜的情況，比如兩個或更多的集合元素或事件。</p><h3 id="單元素場景" tabindex="-1">單元素場景 <a class="header-anchor" href="#單元素場景" aria-label="Permalink to “單元素場景”">​</a></h3><p>在上一篇文章的代碼基礎上，向虛擬購物筐裏添加一些商品。首先，寫一個偽測試：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Fact]</span></span>
<span class="line"><span>public void Add1ItemBasketHas1Item() {</span></span>
<span class="line"><span>        var expectedNoOfItems = 1;</span></span>
<span class="line"><span>        var actualNoOfItems = 0;</span></span>
<span class="line"><span>        Assert.Equal(expectedNoOfItems, actualNoOfItems);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>不出所料，這個測試失敗了，因為硬編碼了一個錯誤的值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Starting test execution, please wait...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>A total of 1 test files matched the specified pattern.</span></span>
<span class="line"><span>[xUnit.net 00:00:00.57] tests.UnitTest1.NewlyCreatedBasketHas0Items [FAIL]</span></span>
<span class="line"><span>  X tests.UnitTest1.NewlyCreatedBasketHas0Items [4ms]</span></span>
<span class="line"><span>  Error Message:</span></span>
<span class="line"><span>   Assert.Equal() Failure</span></span>
<span class="line"><span>Expected: 0</span></span>
<span class="line"><span>Actual: 1</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>現在是時候停止偽造了。現在你已經用 <code>ArrayList</code> 實現了購物筐。那麼應該怎麼實現<em>商品</em>呢？</p><p>簡潔性應該一直是你的指導原則。在不瞭解商品的太多信息的情況下，你可以先用另一個集合來實現它。這個表示商品的集合應該包含些什麼呢？由於你多半會關心計算購物筐中的商品總價，所以對商品的表示至少需要包含價格（可以是任意貨幣，為簡單起見，不妨假設是人民幣）。</p><p>（我們需要）一個簡單的集合類型，它包含一個商品 ID（可以在系統中的其它地方使用 ID 來指向該商品）和這個商品的價格。</p><p>鍵值對類型的數據結構可以很容易滿足這個需求。在 C# 中最先被想到的數據結構就是 <code>Hashtable</code>。</p><p>在購物應用的代碼中給 <code>IShoppingAPI</code> 增加一個新功能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int AddItem(Hashtable item);</span></span></code></pre></div><p>這個新功能以一個用 <code>Hashtable</code> 表示的商品為輸入，返回購物筐中的商品數量。</p><p>將測試代碼中硬編碼的值提替換為對接口的調用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Fact]</span></span>
<span class="line"><span>public void Add1ItemBasketHas1Item() {            </span></span>
<span class="line"><span>    var expectedNoOfItems = 1;</span></span>
<span class="line"><span>    Hashtable item = [new][3] Hashtable();</span></span>
<span class="line"><span>    var actualNoOfItems = shoppingAPI.AddItem(item);</span></span>
<span class="line"><span>    Assert.Equal(expectedNoOfItems, actualNoOfItems);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在上面的代碼中實例化了一個 <code>Hashtable</code> 並命名為 <code>item</code>，然後調用購物接口中的 <code>AddItem(item)</code> 方法，該方法會返回購物筐中實際的商品數量。</p><p>轉到 <code>ShoppingAPI</code> 類中，實現這個方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>public int AddItem(Hashtable item) {</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>這裏再次通過寫假代碼來檢驗測試的效果（測試是業務代碼的第一個調用者）。如果測試失敗，將硬編碼值換成實際的代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>public int AddItem(Hashtable item) {</span></span>
<span class="line"><span>    basket.Add(item);</span></span>
<span class="line"><span>    return basket.Count;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在上面的代碼中，向購物筐裏添加了一件商品，然後返回購物筐中的商品數量：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Test Run Successful.</span></span>
<span class="line"><span>Total tests: 2</span></span>
<span class="line"><span>     Passed: 2</span></span>
<span class="line"><span> Total time: 1.0633 Seconds</span></span></code></pre></div><p>到目前為止，你通過了兩個測試，同時也基本里解了 ZOMBIES 方法中的最簡場景和單元素場景兩部分。</p><h3 id="反思總結" tabindex="-1">反思總結 <a class="header-anchor" href="#反思總結" aria-label="Permalink to “反思總結”">​</a></h3><p>回顧前面所做的工作，你會發現通過將注意力集中到處理最簡場景和單元素場景上，你在構建接口的同時也定義了一些業務邏輯邊界！這不是很棒嗎？現在你已經部分地實現了最關鍵的抽象邏輯，並且能夠處理什麼也沒有和只有一個元素的的情況。因為你正在構建的是一個電子交易 API，所以你不能對顧客的購物行為預設其它限制。總而言之，虛擬購物筐應該是無限大的。</p><p>ZOMBIES 提供的逐步優化思路的另一個重要方面（雖然不是很明顯）是從大概思路到具體實現的阻力。你也許已經注意到了，要具體實現某個東西總是困難重重。倒不如先用硬編碼值來構造一個偽實現。只有看到接口與測試之間以一種合理的方式交互之後，你才會願意開始完善實現代碼。</p><p>即便如此，你也應該採用簡單直接的代碼結構，儘可能避免條件邏輯分支。</p><h3 id="多元素場景" tabindex="-1">多元素場景 <a class="header-anchor" href="#多元素場景" aria-label="Permalink to “多元素場景”">​</a></h3><p>通過定義顧客向購物筐裏添加兩件商品時的期望來拓展應用程序。首先構造一個偽測試。它的期望值為 2，但是現在將實際值硬編碼為 0，強制讓測試失敗：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Fact]</span></span>
<span class="line"><span>public void Add2ItemsBasketHas2Items() {</span></span>
<span class="line"><span>        var expectedNoOfItems = 2;</span></span>
<span class="line"><span>        var actualNoOfItems = 0;</span></span>
<span class="line"><span>        Assert.Equal(expectedNoOfItems, actualNoOfItems);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>執行測試，前兩個測試用例通過了（針對最簡場景和單元素場景的測試），而硬編碼的測試不出所料地失敗了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>A total of 1 test files matched the specified pattern.</span></span>
<span class="line"><span>[xUnit.net 00:00:00.57] tests.UnitTest1.Add2ItemsBasketHas2Items [FAIL]</span></span>
<span class="line"><span>  X tests.UnitTest1.Add2ItemsBasketHas2Items [2ms]</span></span>
<span class="line"><span>  Error Message:</span></span>
<span class="line"><span>   Assert.Equal() Failure</span></span>
<span class="line"><span>Expected: 2</span></span>
<span class="line"><span>Actual: 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Test Run Failed.</span></span>
<span class="line"><span>Tatal tests: 3</span></span>
<span class="line"><span>     Passed: 2</span></span>
<span class="line"><span>     Failed: 1</span></span></code></pre></div><p>將硬編碼值替換為實際的代碼調用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Fact]</span></span>
<span class="line"><span>public void Add2ItemsBasketHas2Items() {</span></span>
<span class="line"><span>        var expectedNoOfItems = 2;</span></span>
<span class="line"><span>        Hashtable item = [new][3] Hashtable();</span></span>
<span class="line"><span>        shoppingAPI.AddItem(item);</span></span>
<span class="line"><span>        var actualNoOfItems = shoppingAPI.AddItem(item);</span></span>
<span class="line"><span>        Assert.Equal(expectedNoOfItems, actualNoOfItems);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在這個測試中，你向購物筐中添加了兩件商品（實際上是將同一件商品添加了兩次），然後比較期望的商品數量和第二次添加商品後調用 <code>shoppingAPI</code> 返回的商品數量是否相等。</p><p>現在所有測試都能夠通過！</p><h3 id="敬請期待" tabindex="-1">敬請期待 <a class="header-anchor" href="#敬請期待" aria-label="Permalink to “敬請期待”">​</a></h3><p>現在你已經瞭解了最簡場景、單元素場景和多元素場景。我將下一篇文章中介紹邊界行為和接口定義。敬請期待!</p><p>（題圖：MJ/e4679f1f-311a-4a41-80e8-8d2834b956f2）</p><hr>`,44)),n("p",null,[s[4]||(s[4]=a("via: ",-1)),t(e,{href:"https://opensource.com/article/21/2/build-expand-software"},{default:p(()=>[...s[3]||(s[3]=[a("https://opensource.com/article/21/2/build-expand-software",-1)])]),_:1})]),n("p",null,[s[9]||(s[9]=a("作者：",-1)),t(e,{href:"https://opensource.com/users/alex-bunardzic"},{default:p(()=>[...s[5]||(s[5]=[a("Alex Bunardzic",-1)])]),_:1}),s[10]||(s[10]=a(" 選題：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),t(e,{href:"https://github.com/toknow-gh"},{default:p(()=>[...s[7]||(s[7]=[a("toknow-gh",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[15]||(s[15]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const v=i(c,[["render",h]]);export{x as __pageData,v as default};
